def _is_valid_riffle_merge(deck, out):
    """True iff `out` preserves relative order of some bipartition of `deck`
    (i.e., it is a legal two-packet riffle merge of `deck`)."""
    n = len(deck)
    for k in range(n + 1):
        left, right = deck[:k], deck[k:]
        li = ri = 0
        ok = True
        for x in out:
            if li < len(left) and x == left[li]:
                li += 1
            elif ri < len(right) and x == right[ri]:
                ri += 1
            else:
                ok = False
                break
        if ok:
            return True
    return False

